sql.where:
s.s_active IN (1, 2)

    AND s.s_type = #{spaceVO.typeFilter}


    AND s.s_active = #{spaceVO.activeFilter}


    AND s.s_name LIKE CONCAT('%', #{spaceVO.searchWord}, '%')

mapper.update:
UPDATE space

    b_idx = #{brnIdx},
    s_name         = #{spcName},
    s_type         = #{spcType},
    s_price        = #{spcPrice},
    s_max_capacity = #{spcMaxCapacity},
    s_description  = #{spcDescription}
    , s_img = #{spcImg}

WHERE s_idx = #{spcIdx}

UPDATE space
   SET s_active = #{spcActive}
 WHERE s_idx = #{spcIdx}

UPDATE space
   SET s_active = 1
 WHERE s_idx = #{spcIdx}
